insert into tattoos (slug,title,description,alt_text,styles,placement,featured,sort_order,image_path,image_width,image_height,image_blur,image_tone) values ('deaths-head-moth','Death''s-Head Moth','A death''s-head moth with the skull marking on its thorax, framed by traditional blossoms and four-point sparkles. Bold outline, soft black and grey shading.','Black and grey death''s-head moth tattoo with a skull on its thorax, surrounded by blossoms and four-point sparkles',array['american-traditional','black-grey','gothic']::text[],null,true,11,'/work/deaths-head-moth',1170,1393,'data:image/webp;base64,UklGRmYAAABXRUJQVlA4IFoAAADwAQCdASoNABAAA4BaJYgCdAC5lQNLDgAA/ob4n07kHwEGh8eXX1SrN9yKDAgFIDCH+WdNm7GBGdTV1ve32OQnurIuju2IL7BM3MaHUQAU5PNjsCM2UjIOAAA=','#9b877e') on conflict (slug) do nothing;
insert into tattoos (slug,title,description,alt_text,styles,placement,featured,sort_order,image_path,image_width,image_height,image_blur,image_tone) values ('the-lovers','The Lovers — VI','Tarot card VI. Two skeletons in an embrace inside a hand-drawn card frame, with a rose breaking the top corner.','Tarot card tattoo of The Lovers, numbered VI, showing two skeletons embracing with a rose on the card''s corner',array['black-grey','gothic']::text[],null,true,6,'/work/the-lovers',1170,1212,'data:image/webp;base64,UklGRlgAAABXRUJQVlA4IEwAAAAwAgCdASoPABAAA4BaJYwCdAEWJeqRcN+9gAD2q6PpKCQ97jsVxwtHJaPe01LLi6M8I43NUvsyhV9tlu+pCbkm34G+kgnibq4AoEAA','#9a8a80') on conflict (slug) do nothing;
insert into tattoos (slug,title,description,alt_text,styles,placement,featured,sort_order,image_path,image_width,image_height,image_blur,image_tone) values ('barbed-heart-rose','Barbed Heart Rose','A solid black rose growing through a barbed-wire heart, with blackletter lettering at the centre and ink drips below.','Blackwork tattoo of a solid black rose with a barbed-wire heart and blackletter lettering',array['blackwork','gothic','lettering']::text[],null,true,10,'/work/barbed-heart-rose',1170,1167,'data:image/webp;base64,UklGRmAAAABXRUJQVlA4IFQAAAAwAgCdASoQABAAA4BaJQBOj+AQUpFiLsgPAAD+603kCc4i9MnLyEqT+coLSZEg7GlCRsIBe5KlpQV+aKxIvk9VzX26ZGIM8x1wtyVR0XDVXbYAAAA=','#ac9f95') on conflict (slug) do nothing;
insert into tattoos (slug,title,description,alt_text,styles,placement,featured,sort_order,image_path,image_width,image_height,image_blur,image_tone) values ('seraph-eye','Seraph','Six wings fanning out around a single open eye. Fine black linework with red flame accents tracing the silhouette.','Linework tattoo of a six-winged seraph around a single eye, outlined with red accent flames',array['linework','gothic']::text[],null,true,2,'/work/seraph-eye',1170,1556,'data:image/webp;base64,UklGRlgAAABXRUJQVlA4IEwAAAAwAgCdASoMABAAA4BaJYgCdAD8LjF+ILg/YAD+4ooNKK0tZxh+d7nnyslXt/dWWfQBlBmc46gscURqCZy9VQytVT7k/S7b5+HMAAAA','#a68c7e') on conflict (slug) do nothing;
